#include <iostream>
#include <vector>
#include <algorithm>

static void report(const char* name, int faults, std::vector<int> resident)
{
    std::sort(resident.begin(), resident.end());
    std::cout << name << " faults " << faults << " resident";
    for (int p : resident) std::cout << ' ' << p;
    std::cout << "\n";
}

int main()
{
    int frames{};
    int n{};
    if (!(std::cin >> frames >> n)) return 0;

    std::vector<int> refs;
    for (int i = 0; i < n; ++i)
    {
        int p{};
        std::cin >> p;
        refs.push_back(p);
    }

    /* ---------------- FIFO ---------------- */
    {
        std::vector<int> mem;
        std::size_t next{ 0 };          /* the frame to overwrite */
        int faults{ 0 };
        for (int p : refs)
        {
            bool hit{ false };
            for (int q : mem) if (q == p) { hit = true; break; }
            if (hit) continue;
            ++faults;
            if (static_cast<int>(mem.size()) < frames) mem.push_back(p);
            else { mem[next] = p; next = (next + 1) % mem.size(); }
        }
        report("fifo", faults, mem);
    }

    /* ---------------- LRU ---------------- */
    {
        std::vector<int> mem;           /* front = least recently used */
        int faults{ 0 };
        for (int p : refs)
        {
            auto it = std::find(mem.begin(), mem.end(), p);
            if (it != mem.end())
            {
                mem.erase(it);
                mem.push_back(p);
                continue;
            }
            ++faults;
            if (static_cast<int>(mem.size()) == frames) mem.erase(mem.begin());
            mem.push_back(p);
        }
        report("lru", faults, mem);
    }

    /* ---------------- OPT ---------------- */
    {
        std::vector<int> mem;
        int faults{ 0 };
        for (std::size_t i = 0; i < refs.size(); ++i)
        {
            int p{ refs[i] };
            if (std::find(mem.begin(), mem.end(), p) != mem.end()) continue;
            ++faults;
            if (static_cast<int>(mem.size()) < frames) { mem.push_back(p); continue; }

            /* Evict whichever resident page is next used furthest away,
               preferring one that is never used again. */
            std::size_t victim{ 0 };
            std::size_t best{ 0 };
            for (std::size_t j = 0; j < mem.size(); ++j)
            {
                std::size_t when{ refs.size() };     /* never */
                for (std::size_t t = i + 1; t < refs.size(); ++t)
                    if (refs[t] == mem[j]) { when = t; break; }
                if (when > best) { best = when; victim = j; }
            }
            mem[victim] = p;
        }
        report("opt", faults, mem);
    }

    return 0;
}
